"""Prepare provenance and an offline production-reference viewer; no image editing."""
from pathlib import Path
from PIL import Image
import hashlib, html, json

ROOT = Path(__file__).resolve().parent
manifest_path = ROOT / 'generation-manifest.json'
manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
for item in manifest['assets']:
    path = ROOT / item['file']
    with Image.open(path) as image:
        item.update(width=image.width, height=image.height, mode=image.mode)
        if 'A' in image.getbands():
            alpha = image.getchannel('A')
            bbox = alpha.point(lambda x: 255 if x > 16 else 0).getbbox()
            item['alpha_extrema'] = alpha.getextrema()
            item['visible_bbox_alpha_gt_16'] = bbox
            if bbox:
                left, top, right, bottom = bbox
                item['visible_margins_px'] = [left, top, image.width-right, image.height-bottom]
            item['transparent_corners'] = all(alpha.getpixel(p) == 0 for p in ((0,0),(image.width-1,0),(0,image.height-1),(image.width-1,image.height-1)))
    item.update(bytes=path.stat().st_size, sha256=hashlib.sha256(path.read_bytes()).hexdigest())
neutral = next(x for x in manifest['assets'] if x['id'] == 'neutral-front')
if neutral.get('alpha_extrema') != (0,255) or not neutral.get('transparent_corners'):
    raise ValueError('Neutral reference must have real alpha and transparent corners')
if min(neutral['visible_margins_px']) <= 0:
    raise ValueError('Character touches a canvas edge')
manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')

layers = json.loads((ROOT/'layer-checklist.json').read_text(encoding='utf-8'))
layer_count = sum(len(x['parts']) for x in layers['groups'])
rows = ''.join(f'<tr><th>{html.escape(x["title"])}</th><td>{len(x["parts"])}</td><td>{html.escape(x["notes"])}</td></tr>' for x in layers['groups'])
page = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>大肥鱼 · 首版制作准备</title><style>
:root{color-scheme:dark;font-family:"Microsoft YaHei UI",sans-serif;background:#111d24;color:#deebef}*{box-sizing:border-box}body{margin:0}header,main{max-width:1450px;margin:auto;padding:28px 4vw}header{padding-top:36px;border-bottom:1px solid #37525e}.micro{font-size:11px;letter-spacing:2px;color:#8ad4dc}h1{font-size:28px;letter-spacing:1px;margin:10px 0 15px}h2{font-size:19px;font-weight:500;margin:0 0 14px}p{font-size:13px;line-height:1.9;color:#b8ced7;margin:10px 0}a{color:#9cdee6;text-decoration:none}a:hover{text-decoration:underline}nav{display:flex;flex-wrap:wrap;gap:20px;font-size:12px;margin-top:18px}.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:24px}.step{border:1px solid #3c5663;background:#192d37;padding:12px 14px;font-size:12px}.step b{display:block;margin-bottom:7px;font-weight:500}.step span{font-size:10px;color:#91aebd}.step.done{border-color:#6ea8ad}.step.done span{color:#a2dcd6}.layout{display:grid;grid-template-columns:minmax(300px,.9fr) minmax(400px,1.2fr);gap:22px}section.panel{background:#172832;border:1px solid #3b5561;padding:19px}.stage{height:520px;border:1px solid #4d6470;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#172129}.stage[data-background="light"]{background:#e6e6df}.stage[data-background="checker"]{background-color:#c5cbcf;background-image:linear-gradient(45deg,#9faeb7 25%,transparent 25%),linear-gradient(-45deg,#9faeb7 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#9faeb7 75%),linear-gradient(-45deg,transparent 75%,#9faeb7 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.stage img{height:100%;max-width:100%;object-fit:contain;transform:scale(var(--scale,1));transform-origin:center}.controls{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:13px 0}button{font:inherit;font-size:12px;border:1px solid #466775;color:#c6dde6;background:#203b47;padding:7px 11px;cursor:pointer}button[aria-pressed="true"]{border-color:#a4dee1;background:#335d65;color:#fff}label{font-size:11px;color:#b3cbd7;display:flex;align-items:center;gap:10px}input{max-width:170px;accent-color:#8dd0d6}.sheet{display:block;width:100%;height:auto;background:#fff}.notice{border-left:3px solid #8ed0d3;background:#203a46;padding:12px 14px;font-size:12px;line-height:1.85;color:#c1dae1;margin-top:20px}.next{margin-top:24px;border:1px solid #3c5967;padding:21px}.next ol{padding-left:21px;line-height:1.95;color:#b7ced8;font-size:13px}.next li{margin-bottom:8px}.next strong{color:#e2edf0;font-weight:500}details{margin-top:22px;border-top:1px solid #37515f;padding-top:19px}summary{font-size:14px;cursor:pointer;color:#bfd9e1}table{border-collapse:collapse;width:100%;margin-top:16px;font-size:12px;line-height:1.8}th,td{text-align:left;border-bottom:1px solid #334b57;padding:9px;vertical-align:top}th{font-weight:400;color:#deebee;min-width:95px}td{color:#a9c3cf}footer{font-size:11px;color:#8ba7b5;line-height:1.9;margin-top:25px}@media(max-width:950px){.layout{grid-template-columns:1fr}.stage{height:500px}.steps{grid-template-columns:repeat(3,1fr)}}@media(max-width:580px){header,main{padding:22px}h1{font-size:23px}.steps{grid-template-columns:repeat(2,1fr)}.stage{height:420px}section.panel{padding:14px}}
</style></head><body><header><div class="micro">DAFEIYU / CHARACTER PRODUCTION · 01</div><h1>大肥鱼 · 首版制作准备</h1><p>首版外观沿用你接受的动画 Q 版方向。正面立绘用于统一造型，表情表用于统一眉眼嘴形；当前进入拆层原画准备。</p><nav><a href="../facial-prototype/">打开五官可动小样 ↗</a><a href="../../concepts/">返回外观对照</a><a href="制作说明.md">完整制作说明 ↗</a><a href="generation-manifest.json">原图信息与完整提示词 ↗</a></nav></header><main><div class="steps"><div class="step done"><b>01 外观方向</b><span>已接受 · v2方向</span></div><div class="step done"><b>02 制作参考</b><span>正面透明图 + 六表情</span></div><div class="step"><b>03 分层原画</b><span>进行中 · 首批五官小样</span></div><div class="step"><b>04 可动模型</b><span>待绑定与验收</span></div><div class="step"><b>05 面板接入</b><span>待接模型与语音</span></div></div><div class="layout"><section class="panel"><h2>正面中性立绘</h2><div class="stage" id="stage" data-background="checker"><img src="neutral-front.png" alt="大肥鱼正面中性透明立绘" id="neutral"></div><div class="controls" role="group" aria-label="立绘背景"><button data-bg="dark" aria-pressed="false">深色</button><button data-bg="light" aria-pressed="false">浅色</button><button data-bg="checker" aria-pressed="true">棋盘</button><label>显示比例 <input id="zoom" aria-label="立绘显示比例" type="range" min="70" max="140" value="100"><output id="zoomValue">100%</output></label></div><p>已核对真实透明通道，四周保留安全留白。该图尚未拆成独立部件。</p><a href="neutral-front.png" target="_blank">打开透明 PNG 原图 ↗</a></section><section class="panel"><h2>六种表情参考</h2><a href="expression-reference.png" target="_blank"><img class="sheet" src="expression-reference.png" alt="六表情参考：第一排平静、闭眼、开心，第二排生气、委屈、惊讶"></a><p>第一排：平静 · 闭眼 · 开心<br>第二排：生气 · 委屈 · 惊讶</p><p>拆层时统一脸型、眼距和刘海，只改变眉毛、眼皮与嘴形。表情表是绘制参考，尚未成为可切换的模型表情。</p><div class="notice">下一步的关键：绘制真正分层的 PSD，并补齐被头发、衣服挡住的区域。完成后才能绑定自然的眨眼、说话和转头。</div><nav><a href="layer-checklist.json">分层清单 ↗</a><a href="runtime-contract.json">模型参数约定 ↗</a></nav></section></div><section class="next"><h2>后面怎么做</h2><ol><li><strong>分层原画：</strong>眼白、虹膜、眼皮、眉毛、嘴、脸底、发束、身体与鲸尾分别制作，保持同一张画布和位置。</li><li><strong>Live2D 绑定：</strong>先完成眨眼、眼球、嘴开合、头部转动和呼吸，再做头发、尾巴轻摆；保留可编辑工程。</li><li><strong>接入大肥鱼面板：</strong>加载验收通过的模型，将待机、处理任务、等待确认与真实语音播放对应到人物表现。</li></ol><p>DSH继续负责会话、模型和工具执行；人物保持全能虚拟角色的定位。声线与人设细节稍后再定义。</p><details><summary>分层范围 · __LAYER_COUNT__个计划部件，均待制作</summary><table><thead><tr><th>部位</th><th>数量</th><th>绘制要点</th></tr></thead><tbody>__LAYERS__</tbody></table></details></section><footer>本页是离线制作预览，不调用模型或录音。图片由内置图像工具生成，完整提示词和来源已保存。当前尚未创建分层PSD、Cubism工程或本套角色的运行模型；未修改正在运行的DSH插件。<br>制作流程依据 <a href="https://docs.live2d.com/en/cubism-editor-manual/divide-the-material/" target="_blank" rel="noopener noreferrer">Live2D 官方素材分割说明 ↗</a>。</footer></main><script>const stage=document.getElementById('stage');document.querySelectorAll('[data-bg]').forEach(button=>button.addEventListener('click',()=>{stage.dataset.background=button.dataset.bg;document.querySelectorAll('[data-bg]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));}));document.getElementById('zoom').addEventListener('input',event=>{const value=Number(event.target.value);stage.style.setProperty('--scale',value/100);document.getElementById('zoomValue').textContent=value+'%';});</script></body></html>'''
(ROOT/'index.html').write_text(page.replace('__LAYERS__', rows).replace('__LAYER_COUNT__', str(layer_count)), encoding='utf-8')
print(json.dumps({'page':str(ROOT/'index.html'),'planned_parts':layer_count,'neutral_size':[neutral['width'],neutral['height']],'neutral_margins':neutral['visible_margins_px'],'real_alpha':True}, ensure_ascii=False))
